const PptxGenJS = require('pptxgenjs');
const pres = new PptxGenJS();

pres.defineLayout({ name: 'WIDE', width: 13.33, height: 7.5 });
pres.layout = 'WIDE';

const FONT = '微软雅黑';
const PRIMARY = '1F4E79';
const ACCENT = '2E75B6';
const LIGHT_BG = 'D6E4F0';
const WHITE = 'FFFFFF';
const DARK_TEXT = '333333';

// ========== Slide 1: Title ==========
const s1 = pres.addSlide();
s1.background = { color: PRIMARY };
s1.addText('团队协作', {
  x: 0.8, y: 1.8, w: 11.7, h: 1.5,
  fontSize: 48, bold: true, color: WHITE, fontFace: FONT, align: 'center'
});
s1.addText('打造高效协同的工作模式', {
  x: 0.8, y: 3.4, w: 11.7, h: 0.8,
  fontSize: 24, color: 'B4C6E7', fontFace: FONT, align: 'center'
});
s1.addShape(pres.ShapeType.rect, {
  x: 4.5, y: 4.5, w: 4.3, h: 0.06, fill: { color: 'B4C6E7' }
});
s1.addText('2024 · 团队管理系列', {
  x: 0.8, y: 5.2, w: 11.7, h: 0.6,
  fontSize: 16, color: '8FAADC', fontFace: FONT, align: 'center'
});

// ========== Slide 2: Why Team Collaboration Matters ==========
const s2 = pres.addSlide();
s2.background = { color: WHITE };
s2.addShape(pres.ShapeType.rect, {
  x: 0, y: 0, w: 13.33, h: 1.1, fill: { color: PRIMARY }
});
s2.addText('为什么需要团队协作？', {
  x: 0.6, y: 0.15, w: 12, h: 0.8,
  fontSize: 30, bold: true, color: WHITE, fontFace: FONT
});

const reasons = [
  { title: '提升效率', desc: '合理分工让每个人专注擅长领域，\n减少重复劳动，缩短交付周期。' },
  { title: '激发创新', desc: '多元视角碰撞产生新想法，\n跨职能协作推动突破性解决方案。' },
  { title: '增强韧性', desc: '知识共享降低单点风险，\n互相补位确保项目持续推进。' },
  { title: '提升满意度', desc: '归属感与信任感提高参与度，\n良好的协作氛围降低人员流失。' }
];

reasons.forEach((r, i) => {
  const col = i % 2;
  const row = Math.floor(i / 2);
  const bx = 0.6 + col * 6.2;
  const by = 1.5 + row * 2.8;
  s2.addShape(pres.ShapeType.roundRect, {
    x: bx, y: by, w: 5.8, h: 2.4,
    fill: { color: LIGHT_BG }, rectRadius: 0.15
  });
  s2.addText(r.title, {
    x: bx + 0.3, y: by + 0.2, w: 5.2, h: 0.6,
    fontSize: 22, bold: true, color: PRIMARY, fontFace: FONT
  });
  s2.addText(r.desc, {
    x: bx + 0.3, y: by + 0.85, w: 5.2, h: 1.3,
    fontSize: 16, color: DARK_TEXT, fontFace: FONT, lineSpacingMultiple: 1.3
  });
});

// ========== Slide 3: Key Elements ==========
const s3 = pres.addSlide();
s3.background = { color: WHITE };
s3.addShape(pres.ShapeType.rect, {
  x: 0, y: 0, w: 13.33, h: 1.1, fill: { color: PRIMARY }
});
s3.addText('高效协作的四大要素', {
  x: 0.6, y: 0.15, w: 12, h: 0.8,
  fontSize: 30, bold: true, color: WHITE, fontFace: FONT
});

const elements = [
  { icon: '🎯', title: '共同目标', desc: '清晰、可衡量的团队目标\n让所有人朝同一方向努力' },
  { icon: '💬', title: '开放沟通', desc: '建立透明的信息流通机制\n鼓励反馈与积极倾听' },
  { icon: '🤝', title: '信任与尊重', desc: '心理安全的环境让成员\n敢于表达观点和承认错误' },
  { icon: '⚙️', title: '流程与工具', desc: '标准化的协作流程和合适\n的工具减少摩擦与混乱' }
];

elements.forEach((el, i) => {
  const ex = 0.5 + i * 3.15;
  s3.addShape(pres.ShapeType.roundRect, {
    x: ex, y: 1.5, w: 2.9, h: 5.2,
    fill: { color: LIGHT_BG }, rectRadius: 0.15
  });
  s3.addText(el.icon, {
    x: ex, y: 1.8, w: 2.9, h: 1.0,
    fontSize: 44, align: 'center', fontFace: FONT
  });
  s3.addText(el.title, {
    x: ex + 0.2, y: 2.9, w: 2.5, h: 0.7,
    fontSize: 20, bold: true, color: PRIMARY, fontFace: FONT, align: 'center'
  });
  s3.addShape(pres.ShapeType.rect, {
    x: ex + 0.6, y: 3.65, w: 1.7, h: 0.04, fill: { color: ACCENT }
  });
  s3.addText(el.desc, {
    x: ex + 0.2, y: 3.9, w: 2.5, h: 2.4,
    fontSize: 14, color: DARK_TEXT, fontFace: FONT, align: 'center', lineSpacingMultiple: 1.4
  });
});

// ========== Slide 4: Common Challenges & Solutions ==========
const s4 = pres.addSlide();
s4.background = { color: WHITE };
s4.addShape(pres.ShapeType.rect, {
  x: 0, y: 0, w: 13.33, h: 1.1, fill: { color: PRIMARY }
});
s4.addText('常见挑战与应对策略', {
  x: 0.6, y: 0.15, w: 12, h: 0.8,
